<script setup lang="ts">
import type {Template,TemplateInput,Province,Sender} from '../types';
import { reactive, ref } from 'vue';
import FreightBandEditor from './FreightBandEditor.vue';
import ProvinceGroupDialog from './ProvinceGroupDialog.vue';
import { newBand,newTemplate,validateTemplate } from '../templateRules';
import { message } from '../../../components/feedback/message';
const props=defineProps<{template:Template|TemplateInput|null;provinces:Province[];busy:boolean;error:string;sender?:Sender}>();
const emit=defineEmits<{save:[input:TemplateInput];cancel:[]}>();
const initial=props.template?JSON.parse(JSON.stringify(props.template)) as TemplateInput:newTemplate();
if(!props.template && props.sender){initial.originProvince=props.sender.province;initial.originCity=props.sender.city;initial.originCounty=props.sender.county;}
initial.originProvince=props.provinces.find(province=>province.code===initial.originProvince || province.name===initial.originProvince)?.code??initial.originProvince;
const draft=reactive<TemplateInput>(initial),groupIndex=ref<number|null>(null),validation=ref('');
const provinceName=(code:string)=>props.provinces.find(p=>p.code===code)?.name??`${code}（未知地区，请修正）`;
function addGroup(){draft.rules.regionGroups.push({name:`地区组 ${draft.rules.regionGroups.length+1}`,provinces:[],bands:[newBand()]});groupIndex.value=draft.rules.regionGroups.length-1;}
function defaultToggle(event:Event){draft.rules.defaultBands=(event.target as HTMLInputElement).checked?[newBand()]:[];}
function save(){validation.value=validateTemplate(draft);if(validation.value){message.warning(validation.value);return;}const {name,productCode,productName,originProvince,originCity,originCounty,rules,status,remark,version}=draft;emit('save',JSON.parse(JSON.stringify({name,productCode,productName,originProvince,originCity,originCounty,rules,status,remark,version})) as TemplateInput);}
</script>
<template><form data-testid="freight-template-editor" class="space-y-6" @submit.prevent="save"><div class="flex items-start justify-between gap-4"><div><h3 class="text-lg font-bold text-slate-800">{{ template?'编辑合作运费模板':'新建合作运费模板' }}</h3><p class="mt-1 text-xs text-slate-500">按合同填写费率。金额留空表示未配置，填 0 表示明确零元；草稿不参与报价。</p></div><button type="button" :disabled="busy" class="text-sm text-indigo-600" @click="emit('cancel')">返回模板列表</button></div><p v-if="error || validation" role="alert" class="rounded-lg bg-rose-50 p-3 text-sm text-rose-700">{{ error || validation }}</p><fieldset :disabled="busy" class="grid gap-5 md:grid-cols-3"><label>模板名称 *<input v-model.trim="draft.name" name="template-name" required maxlength="100" class="control" placeholder="合同模板名称"></label><label>运输产品编码<input v-model.trim="draft.productCode" class="control" maxlength="100"></label><label>运输产品名称<input v-model.trim="draft.productName" class="control" maxlength="100"></label><label>发货省<select v-model="draft.originProvince" class="control"><option value="">选择发货省份</option><option v-for="p in provinces" :key="p.code" :value="p.code">{{ p.name }}</option><option v-if="draft.originProvince && !provinces.some(p=>p.code===draft.originProvince)" :value="draft.originProvince">{{ draft.originProvince }}（请确认）</option></select></label><label>发货市<input v-model.trim="draft.originCity" class="control" placeholder="市级名称"></label><label>发货区 / 县<input v-model.trim="draft.originCounty" class="control" placeholder="区县名称"></label><label>计价方式<select v-model="draft.rules.mode" name="charge-mode" class="control" @change="draft.rules.volumetric=false"><option value="weight">按重量（kg）</option><option value="piece">按件数（包裹 / 箱）</option></select></label><label>模板状态<select v-model="draft.status" class="control"><option value="disabled">草稿 / 停用</option><option value="enabled">启用并参与报价</option></select></label><div v-if="draft.rules.mode==='weight'" class="self-center"><label class="flex items-center gap-2"><input v-model="draft.rules.volumetric" data-testid="volumetric-toggle" type="checkbox">开启体积重计费</label><label v-if="draft.rules.volumetric" class="mt-3 flex items-center gap-2 text-xs">体积系数<input v-model.number="draft.rules.volumeDivisor" name="volumeDivisor" type="number" min="0.000001" step="any" class="control mt-0 max-w-32"></label></div></fieldset><p v-if="draft.rules.mode==='weight' && draft.rules.volumetric" class="rounded bg-indigo-50 p-3 text-xs text-indigo-700">计费重量取实重与体积重较大值。体积重 kg = 本单体积 m³ × 1,000,000 ÷ 体积系数；缺少体积时无法测算。</p><section class="overflow-hidden rounded-lg border border-slate-200"><header class="flex items-center justify-between border-b bg-slate-50/60 px-4 py-3"><h4 class="font-semibold text-slate-800">默认运费</h4><label class="flex items-center gap-2 text-sm"><input data-testid="default-toggle" type="checkbox" :disabled="busy" :checked="draft.rules.defaultBands.length>0" @change="defaultToggle">启用默认运费</label></header><FreightBandEditor v-if="draft.rules.defaultBands.length" v-model="draft.rules.defaultBands" prefix="default" :mode="draft.rules.mode" :disabled="busy"/><p v-else class="p-4 text-sm text-slate-500">默认运费已关闭，仅对明确指定的省份报价。</p></section><section><header class="mb-3 flex items-center justify-between"><h4 class="font-semibold text-slate-800">指定地区运费</h4><button type="button" :disabled="busy || !provinces.length" class="rounded border border-indigo-200 px-4 py-2 text-sm text-indigo-600 disabled:opacity-40" @click="addGroup">＋ 添加地区组</button></header><p v-if="!draft.rules.regionGroups.length" class="rounded border border-dashed p-6 text-center text-sm text-slate-400">暂无指定地区。指定组优先匹配，组内区间无价格时不会回退默认运费。</p><section v-for="(group,index) in draft.rules.regionGroups" :key="index" class="mb-4 overflow-hidden rounded-lg border border-slate-200"><header class="flex items-start justify-between gap-4 border-b bg-slate-50/60 p-4"><div><h5 class="font-semibold text-slate-800">{{ group.name }}</h5><p class="mt-2 text-sm text-slate-500">{{ group.provinces.map(provinceName).join('、') || '尚未选择省份' }}</p></div><div class="flex shrink-0 gap-4 text-sm"><button type="button" :disabled="busy" class="text-indigo-600" @click="groupIndex=index">选择地区</button><button type="button" :disabled="busy" class="text-rose-600" @click="draft.rules.regionGroups.splice(index,1)">删除组</button></div></header><FreightBandEditor v-model="group.bands" :prefix="`group-${index}`" :mode="draft.rules.mode" :disabled="busy"/></section></section><label class="block">备注<textarea v-model="draft.remark" class="control" rows="2" :disabled="busy" maxlength="1000" placeholder="仅记录合同说明，备注不参与费用计算"/></label><footer class="flex items-center justify-between border-t pt-4"><p class="text-xs text-slate-500">区间 (下限, 上限]，∞ 为无上限；整单按命中区间计价，续量向上取整。</p><button :disabled="busy" class="shrink-0 rounded-lg bg-indigo-500 px-6 py-2.5 text-sm font-semibold text-white disabled:opacity-40">{{ busy?'保存中…':'保存运费模板' }}</button></footer><ProvinceGroupDialog v-if="groupIndex!==null" :key="groupIndex" :groups="draft.rules.regionGroups" :group-index="groupIndex" :provinces="provinces" @save="draft.rules.regionGroups=$event;groupIndex=null" @close="groupIndex=null"/></form></template>
<style scoped>label{@apply text-sm text-slate-600;}.control{@apply mt-2 block w-full rounded-lg border border-slate-200 bg-white px-3 py-2 text-sm text-slate-800 outline-none focus:border-indigo-400;}button:disabled{@apply opacity-40;}</style>
